static void CLOCK_incrementWidget ()
{     
    
    SC_CLOCK_data_t clockSignal = RTE_SC_CLOCK_get(&SO_CLOCK_signal);
    if(clockSignal.activeWidget == W_HOURS)
    {
        if(m_hours < 23)
            m_hours ++;
        else 
            m_hours = 0;
        clockSignal.clockValue.hours = m_hours;
        
    }
    else if(clockSignal.activeWidget == W_MINUTES)
    {
        if(m_mins < 59)
            m_mins ++;
        else 
        {  
            if(clockSignal.StateMachine_ptr->m_state == CLOCK_C_ISDISPLAYING)
            {
                if(m_hours < 23)
                    m_hours++;
                else 
                    m_hours = 0;
                clockSignal.clockValue.hours = m_hours;  
            }
            m_mins = 0;
        }
        clockSignal.clockValue.mins = m_mins;  
    }
    RTE_SC_CLOCK_set(&SO_CLOCK_signal,clockSignal);    
}

static void CLOCK_setEditFonts ()
{  
    if(SO_CLOCK_signal.value.activeWidget == W_HOURS)
    {
        SO_CLOCK_signal.value.clockValue.font_hours.F_TEXT_COLOR = BLACK;
        SO_CLOCK_signal.value.clockValue.font_hours.F_BG_COLOR = WHITE;
        SO_CLOCK_signal.value.clockValue.font_mins.F_TEXT_COLOR = WHITE;
        SO_CLOCK_signal.value.clockValue.font_mins.F_BG_COLOR = BLACK;
    }
    else if(SO_CLOCK_signal.value.activeWidget == W_MINUTES)
    {
        SO_CLOCK_signal.value.clockValue.font_hours.F_TEXT_COLOR = WHITE;
        SO_CLOCK_signal.value.clockValue.font_hours.F_BG_COLOR = BLACK;
        SO_CLOCK_signal.value.clockValue.font_mins.F_TEXT_COLOR = BLACK;
        SO_CLOCK_signal.value.clockValue.font_mins.F_BG_COLOR = WHITE;
    }
    
}

static void CLOCK_setDisplayFonts ()
{  
    SO_CLOCK_signal.value.clockValue.font_hours.F_TEXT_COLOR = WHITE;
    SO_CLOCK_signal.value.clockValue.font_hours.F_BG_COLOR = BLACK;
    SO_CLOCK_signal.value.clockValue.font_mins.F_TEXT_COLOR = WHITE;
    SO_CLOCK_signal.value.clockValue.font_mins.F_BG_COLOR = BLACK;
      
    
}

static void CLOCK__dispatchWrapper(EVENT_ENUM_t ev, WIDGET_type_t activeWidget)
{           
    SO_CLOCK_signal.value.activeWidget = activeWidget;
    STATE_processEvent(&CONTROL_WidgetFSM, ev);        
}
