void tftDisplay( char* time_hours, char* time_mins)
{    
    TFT_setCursor(5, 40);
    TFT_setColors(SO_CLOCK_signal.value.clockValue.font_hours.F_TEXT_COLOR,SO_CLOCK_signal.value.clockValue.font_hours.F_BG_COLOR);
    TFT_print(time_hours);
    TFT_setColors(WHITE,BLACK);
    TFT_print(":");
    TFT_setColors(SO_CLOCK_signal.value.clockValue.font_mins.F_TEXT_COLOR,SO_CLOCK_signal.value.clockValue.font_mins.F_BG_COLOR);
    TFT_print(time_mins);
}

